self.FORGE_DB_SQL = "-- =============================================================================\n--  QueryForge reference database — SCHEMA\n--\n--  An order-fulfilment system, written to be READ. Every non-obvious decision is\n--  commented where it was made, not in a document nobody opens.\n--\n--  Dialect: written for SQLite so the in-browser playground can run it unchanged.\n--  Where a production engine would spell something differently, the comment says\n--  so. The DESIGN is dialect-independent; see reference/README.md for the\n--  PostgreSQL and SQL Server variants of the three places it matters.\n--\n--  Covered in: site/chapters/04-ddl-and-constraints.html\n--              site/chapters/24-concurrency-patterns.html\n--              course/module-02-modelling/README.md\n-- =============================================================================\n\nPRAGMA foreign_keys = ON;   -- SQLite does NOT enforce FKs unless you ask. See ch. 04.\n\n-- ---------------------------------------------------------------- geography --\n-- Split out because city -> region is a transitive dependency on the customer\n-- key, which is exactly what 3NF forbids. See chapter 05.\n\nCREATE TABLE regions (\n  id    INTEGER PRIMARY KEY,\n  name  TEXT NOT NULL,\n  CONSTRAINT uq_regions_name UNIQUE (name)\n);\n\nCREATE TABLE cities (\n  id         INTEGER PRIMARY KEY,\n  name       TEXT    NOT NULL,\n  region_id  INTEGER NOT NULL REFERENCES regions(id),\n  CONSTRAINT uq_cities_name_region UNIQUE (name, region_id)\n);\n-- The index a foreign key does NOT create for you. Without it, deleting a region\n-- scans every city to prove nothing references it — and holds locks while it does.\nCREATE INDEX ix_cities_region ON cities (region_id);\n\n-- ---------------------------------------------------------------- customers --\n\nCREATE TABLE customers (\n  id          INTEGER PRIMARY KEY,           -- surrogate: stable, narrow, meaningless\n  vat_number  TEXT    NULL,                  -- NULL is legitimate: private customers have none\n  email       TEXT    NOT NULL,\n  name        TEXT    NOT NULL,\n  city_id     INTEGER NOT NULL REFERENCES cities(id),\n  created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  deleted_at  TEXT    NULL,                  -- soft delete: see the note below\n\n  -- The natural keys, still enforced. A surrogate id INSTEAD of these constraints\n  -- is the actual mistake people make, and it is how you get two rows for one\n  -- customer. See chapter 02.\n  CONSTRAINT uq_customers_email UNIQUE (email),\n  CONSTRAINT uq_customers_vat   UNIQUE (vat_number),   -- multiple NULLs are allowed\n  CONSTRAINT ck_customers_email CHECK (email LIKE '%_@_%.__%')\n);\nCREATE INDEX ix_customers_city ON customers (city_id);\n-- Partial index: only live customers, which is what almost every query wants,\n-- and it keeps the index small. PostgreSQL and SQL Server spell this the same way.\nCREATE INDEX ix_customers_live ON customers (name) WHERE deleted_at IS NULL;\n\n-- WHY SOFT DELETE. \"Delete the customer\" almost never means \"destroy seven years\n-- of invoices\", and in Italy a tax authority would have opinions. ON DELETE\n-- CASCADE would let one statement remove rows from tables it does not name, with\n-- a row count that gives no clue about the damage. See chapter 04.\n\n-- ----------------------------------------------------------------- products --\n\nCREATE TABLE products (\n  id                INTEGER PRIMARY KEY,\n  sku               TEXT    NOT NULL,\n  name              TEXT    NOT NULL,\n  -- MONEY IS NEVER A FLOAT. Integer minor units: exact, comparable, fast, and the\n  -- unit is in the column name so nobody has to guess. See chapter 03.\n  list_price_cents  INTEGER NOT NULL,\n  discontinued      INTEGER NOT NULL DEFAULT 0,   -- SQLite has no BOOLEAN; 0/1 with a CHECK\n\n  CONSTRAINT uq_products_sku       UNIQUE (sku),\n  CONSTRAINT ck_products_price     CHECK (list_price_cents >= 0),\n  CONSTRAINT ck_products_disc_bool CHECK (discontinued IN (0, 1))\n);\n\nCREATE TABLE stock (\n  product_id  INTEGER PRIMARY KEY REFERENCES products(id),\n  on_hand     INTEGER NOT NULL,\n  reserved    INTEGER NOT NULL DEFAULT 0,\n  -- The invariant that makes overselling impossible. Two sessions reserving the\n  -- last unit is the classic race; this constraint means the loser gets an error\n  -- rather than a negative stock level. See chapter 24.\n  CONSTRAINT ck_stock_nonneg    CHECK (on_hand >= 0 AND reserved >= 0),\n  CONSTRAINT ck_stock_reservable CHECK (reserved <= on_hand)\n);\n\n-- ------------------------------------------------------------------- orders --\n--\n--  The state machine:\n--\n--      draft -> submitted -> confirmed -> shipped -> delivered\n--        |          |            |\n--        +----------+------------+--> cancelled\n--\n--  Note what is NOT there: shipped -> cancelled. Once it is on a lorry, \"cancel\"\n--  is a returns process with different accounting, not a status change. Encoding\n--  that refusal is the difference between a state machine and a status column.\n\nCREATE TABLE orders (\n  id            INTEGER PRIMARY KEY,\n  customer_id   INTEGER NOT NULL REFERENCES customers(id),\n  status        TEXT    NOT NULL DEFAULT 'draft',\n  placed_at     TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  shipped_at    TEXT    NULL,\n  delivered_at  TEXT    NULL,\n  total_cents   INTEGER NOT NULL DEFAULT 0,\n\n  -- OPTIMISTIC CONCURRENCY. Every write does\n  --     UPDATE orders SET ..., version = version + 1\n  --      WHERE id = ? AND version = ?\n  -- and zero rows affected means somebody else got there first -> 409, retry.\n  -- Cheaper than holding a lock across a user's thinking time, and it does not\n  -- deadlock. In SQL Server this would be a `rowversion`; in PostgreSQL an\n  -- `xmin` comparison also works. See chapter 24.\n  version       INTEGER NOT NULL DEFAULT 1,\n\n  CONSTRAINT ck_orders_status CHECK (status IN\n    ('draft','submitted','confirmed','shipped','delivered','cancelled')),\n  CONSTRAINT ck_orders_total  CHECK (total_cents >= 0),\n  -- Shipped implies a ship date, and it cannot precede the order.\n  CONSTRAINT ck_orders_shipped CHECK (\n    status NOT IN ('shipped','delivered')\n    OR (shipped_at IS NOT NULL AND shipped_at >= placed_at)),\n  CONSTRAINT ck_orders_delivered CHECK (\n    status <> 'delivered'\n    OR (delivered_at IS NOT NULL AND delivered_at >= shipped_at))\n);\nCREATE INDEX ix_orders_customer  ON orders (customer_id);\n-- Composite, in this order, because the common query is \"this customer's recent\n-- orders\". (customer_id, placed_at) supports that AND \"this customer's orders\";\n-- (placed_at, customer_id) supports neither well. See chapter 26.\nCREATE INDEX ix_orders_cust_date ON orders (customer_id, placed_at DESC);\nCREATE INDEX ix_orders_status    ON orders (status, placed_at);\n\nCREATE TABLE order_lines (\n  order_id          INTEGER NOT NULL REFERENCES orders(id),\n  line_no           INTEGER NOT NULL,\n  product_id        INTEGER NOT NULL REFERENCES products(id),\n  quantity          INTEGER NOT NULL,\n  -- NOT a normalisation violation. products.list_price_cents is the CURRENT price;\n  -- this is the price this customer was actually charged on that day. Normalise it\n  -- away and reprinting last year's invoice silently reprices it. See chapter 05.\n  unit_price_cents  INTEGER NOT NULL,\n\n  -- line_no is an explicit column because a relation has no order. See chapter 02.\n  PRIMARY KEY (order_id, line_no),\n  CONSTRAINT ck_lines_qty   CHECK (quantity > 0),\n  CONSTRAINT ck_lines_price CHECK (unit_price_cents >= 0),\n  CONSTRAINT uq_lines_product UNIQUE (order_id, product_id)   -- one line per product\n);\nCREATE INDEX ix_lines_product ON order_lines (product_id);\n\nCREATE TABLE payments (\n  id            INTEGER PRIMARY KEY,\n  order_id      INTEGER NOT NULL REFERENCES orders(id),\n  amount_cents  INTEGER NOT NULL,\n  method        TEXT    NOT NULL,\n  paid_at       TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  -- The idempotency key. An ETL job or a payment webhook that is re-delivered\n  -- must not create a second payment. UNIQUE turns \"did we already do this?\"\n  -- from a race into a constraint violation you can catch. See chapter 20.\n  external_ref  TEXT    NOT NULL,\n\n  CONSTRAINT uq_payments_ref    UNIQUE (external_ref),\n  CONSTRAINT ck_payments_amount CHECK (amount_cents > 0),\n  CONSTRAINT ck_payments_method CHECK (method IN ('card','transfer','cash','credit'))\n);\nCREATE INDEX ix_payments_order ON payments (order_id);\n\n-- ------------------------------------------------------------------- events --\n-- Domain events, written inside the same transaction as the state change they\n-- describe. That is what makes them trustworthy: there is no window in which the\n-- order moved but the event did not.\n\nCREATE TABLE order_events (\n  id          INTEGER PRIMARY KEY,\n  order_id    INTEGER NOT NULL REFERENCES orders(id),\n  from_status TEXT    NULL,          -- NULL on creation: there was no previous status\n  to_status   TEXT    NOT NULL,\n  at          TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  actor       TEXT    NOT NULL DEFAULT 'system'\n);\nCREATE INDEX ix_events_order ON order_events (order_id, at);\n\n-- THE TRANSACTIONAL OUTBOX.\n-- The problem: \"save the order AND send the email\" spans two systems, and there\n-- is no transaction across both. Send first and the save may fail; save first and\n-- the send may fail. The outbox makes the message part of the SAME transaction as\n-- the data, and a separate worker delivers it afterwards — at-least-once, so the\n-- consumer must be idempotent. See chapter 24 and course/module-08-outbox.\nCREATE TABLE outbox (\n  id            INTEGER PRIMARY KEY,\n  topic         TEXT    NOT NULL,\n  payload       TEXT    NOT NULL,          -- JSON. See chapter 18 for why it is a blob here\n  created_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  claimed_at    TEXT    NULL,\n  claimed_by    TEXT    NULL,\n  published_at  TEXT    NULL,\n  attempts      INTEGER NOT NULL DEFAULT 0\n);\n-- The worker's query is \"unpublished, oldest first\". A partial index on exactly\n-- that predicate stays tiny however large the table grows, because published rows\n-- leave the index entirely. See chapter 26.\nCREATE INDEX ix_outbox_pending ON outbox (created_at) WHERE published_at IS NULL;\n\n-- ---------------------------------------------------------------- employees --\n-- Present so the course has a real hierarchy to run recursive CTEs against.\n\nCREATE TABLE employees (\n  id          INTEGER PRIMARY KEY,\n  name        TEXT    NOT NULL,\n  manager_id  INTEGER NULL REFERENCES employees(id),   -- self-referencing; NULL = the root\n  hired_at    TEXT    NOT NULL,\n  salary_cents INTEGER NOT NULL,\n  CONSTRAINT ck_employees_salary CHECK (salary_cents > 0),\n  CONSTRAINT ck_employees_not_own_manager CHECK (manager_id <> id)\n);\nCREATE INDEX ix_employees_manager ON employees (manager_id);\n\n-- --------------------------------------------------------------- dim_date ----\n-- The calendar table nobody teaches and every reporting system needs. Working\n-- days and holidays are DATA, not arithmetic you reimplement in each query.\n-- See chapter 17.\n\nCREATE TABLE dim_date (\n  d            TEXT    PRIMARY KEY,          -- 'YYYY-MM-DD'\n  year         INTEGER NOT NULL,\n  month        INTEGER NOT NULL,\n  day          INTEGER NOT NULL,\n  quarter      INTEGER NOT NULL,\n  iso_week     INTEGER NOT NULL,\n  day_of_week  INTEGER NOT NULL,             -- 0 = Sunday, SQLite's %w\n  is_weekend   INTEGER NOT NULL,\n  is_holiday   INTEGER NOT NULL DEFAULT 0,\n  holiday_name TEXT    NULL,\n  CONSTRAINT ck_dim_date_flags CHECK (is_weekend IN (0,1) AND is_holiday IN (0,1))\n);\nCREATE INDEX ix_dim_date_ym ON dim_date (year, month);\n\n-- ------------------------------------------------------------------- views ---\n-- A view is an API over the schema: it lets the tables change underneath without\n-- every report changing with them. It is NOT a performance feature — the query is\n-- expanded into whatever uses it. See chapter 33.\n\nCREATE VIEW v_order_totals AS\nSELECT\n  o.id                AS order_id,\n  o.customer_id,\n  o.status,\n  o.placed_at,\n  -- Pre-aggregated per branch, so joining lines AND payments cannot fan out.\n  -- See chapter 08.\n  COALESCE(l.line_total_cents, 0) AS line_total_cents,\n  COALESCE(p.paid_cents, 0)       AS paid_cents,\n  COALESCE(l.line_total_cents, 0) - COALESCE(p.paid_cents, 0) AS outstanding_cents\nFROM orders o\nLEFT JOIN (SELECT order_id, SUM(quantity * unit_price_cents) AS line_total_cents\n           FROM order_lines GROUP BY order_id) l ON l.order_id = o.id\nLEFT JOIN (SELECT order_id, SUM(amount_cents) AS paid_cents\n           FROM payments GROUP BY order_id)    p ON p.order_id = o.id;\n\nCREATE VIEW v_orders_geo AS\nSELECT o.*, c.name AS customer_name, ci.name AS city, r.name AS region\nFROM orders o\nJOIN customers c ON c.id = o.customer_id\nJOIN cities    ci ON ci.id = c.city_id\nJOIN regions   r ON r.id = ci.region_id;\n\n-- =============================================================================\n--  QueryForge reference database — SEED\n--\n--  Deliberately DETERMINISTIC. No random(): the same file always produces the\n--  same database, so a lab exercise can assert an exact answer and the integrity\n--  gate can check that the answers in course/SOLUTIONS.md are still right.\n--  Pseudo-randomness comes from arithmetic on the row number, which is\n--  reproducible on every engine.\n--\n--  Volume: ~40 customers, 24 products, ~1 800 orders, ~4 400 order lines,\n--  ~1 500 payments, 731 calendar days. Small enough to load in a browser in\n--  under a second; large enough that a missing index is visible in a plan.\n-- =============================================================================\n\n-- ------------------------------------------------------------------ geography\nINSERT INTO regions (id, name) VALUES\n  (1,'Emilia-Romagna'), (2,'Lombardia'), (3,'Veneto'), (4,'Toscana'), (5,'Piemonte');\n\nINSERT INTO cities (id, name, region_id) VALUES\n  (1,'Bologna',1), (2,'Modena',1), (3,'Parma',1), (4,'Reggio Emilia',1), (5,'Rimini',1),\n  (6,'Milano',2), (7,'Bergamo',2), (8,'Brescia',2),\n  (9,'Venezia',3), (10,'Verona',3), (11,'Padova',3),\n  (12,'Firenze',4), (13,'Pisa',4),\n  (14,'Torino',5), (15,'Novara',5);\n\n-- ------------------------------------------------------------------- products\nINSERT INTO products (id, sku, name, list_price_cents, discontinued) VALUES\n  (1,'CNC-100','Fresa CNC 3 assi',              1249000, 0),\n  (2,'CNC-200','Fresa CNC 5 assi',              2899000, 0),\n  (3,'TRN-050','Tornio da banco',                489000, 0),\n  (4,'BLT-010','Nastro trasportatore 2 m',       159000, 0),\n  (5,'BLT-020','Nastro trasportatore 5 m',       329000, 0),\n  (6,'PLC-001','Controllore PLC compatto',        89900, 0),\n  (7,'PLC-002','Controllore PLC modulare',       184900, 0),\n  (8,'SNS-100','Sensore di prossimità',            4900, 0),\n  (9,'SNS-200','Sensore di temperatura',           7900, 0),\n  (10,'SNS-300','Encoder rotativo',                12900, 0),\n  (11,'MTR-050','Motore passo-passo NEMA 23',      15900, 0),\n  (12,'MTR-100','Servomotore 750 W',              129000, 0),\n  (13,'CBL-001','Cavo schermato 10 m',              3900, 0),\n  (14,'CBL-002','Cavo schermato 25 m',              8900, 0),\n  (15,'PNL-001','Quadro elettrico IP54',           74900, 0),\n  (16,'PNL-002','Quadro elettrico IP66',          109000, 0),\n  (17,'VLV-010','Elettrovalvola 1/4\"',             11900, 0),\n  (18,'VLV-020','Elettrovalvola 1/2\"',             16900, 0),\n  (19,'PMP-100','Pompa idraulica 5 kW',           229000, 0),\n  (20,'FLT-001','Filtro aria industriale',         21900, 0),\n  (21,'GRB-100','Pinza pneumatica',                45900, 0),\n  (22,'RBT-001','Braccio robotico 6 assi',       3450000, 0),\n  (23,'OLD-001','Fresa CNC 2 assi (fuori catalogo)', 799000, 1),\n  (24,'OLD-002','PLC serie precedente',             59900, 1);\n\nINSERT INTO stock (product_id, on_hand, reserved)\nSELECT id,\n       CASE WHEN discontinued = 1 THEN 0 ELSE 12 + (id * 7) % 90 END,\n       CASE WHEN discontinued = 1 THEN 0 ELSE (id * 3) % 5 END\nFROM products;\n\n-- ------------------------------------------------------------------ customers\n-- Deliberately imperfect data, because real data is: two customers with no VAT\n-- number (private buyers), one soft-deleted, and a spread of cities that makes\n-- GROUP BY interesting.\nINSERT INTO customers (id, vat_number, email, name, city_id, created_at, deleted_at)\nWITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM seq WHERE n < 40)\nSELECT\n  n,\n  CASE WHEN n IN (17, 33) THEN NULL\n       ELSE 'IT' || printf('%011d', 12345678900 + n * 137) END,\n  'cliente' || n || '@esempio.it',\n  CASE n % 8\n    WHEN 0 THEN 'Rossi Meccanica SpA'   WHEN 1 THEN 'Bianchi Automazione Srl'\n    WHEN 2 THEN 'Verdi Impianti Srl'    WHEN 3 THEN 'Ferrari Componenti SpA'\n    WHEN 4 THEN 'Conti Robotica Srl'    WHEN 5 THEN 'Galli Sistemi SpA'\n    WHEN 6 THEN 'Marchetti Utensili Srl' ELSE 'Lombardi Tecnologie Srl'\n  END || ' ' || printf('%02d', n),\n  1 + (n * 7) % 15,          -- 7 is coprime with 15, so all 15 cities are used\n  date('2024-01-01', '+' || ((n * 9) % 400) || ' days') || 'T09:00:00Z',\n  CASE WHEN n = 29 THEN '2026-04-11T14:20:00Z' ELSE NULL END\nFROM seq;\n\n-- ------------------------------------------------------------------ employees\n-- A four-level hierarchy, for the recursive CTE chapter and its labs.\nINSERT INTO employees (id, name, manager_id, hired_at, salary_cents) VALUES\n  (1,'Giulia Ferrero',   NULL, '2018-03-01', 9500000),\n  (2,'Marco Bianchi',       1, '2019-06-17', 6800000),\n  (3,'Elena Rossi',         1, '2019-09-02', 7100000),\n  (4,'Davide Conti',        2, '2020-01-13', 4900000),\n  (5,'Sara Galli',          2, '2021-04-06', 4600000),\n  (6,'Luca Marchetti',      3, '2020-11-23', 5200000),\n  (7,'Chiara Lombardi',     3, '2022-02-14', 4300000),\n  (8,'Paolo Neri',          4, '2022-09-05', 3400000),\n  (9,'Francesca Gatti',     4, '2023-01-09', 3400000),\n  (10,'Alessandro Fabbri',  5, '2023-05-22', 3200000),\n  (11,'Martina Riva',       6, '2023-10-02', 3600000),\n  (12,'Stefano Colombo',    6, '2024-03-11', 3300000),\n  (13,'Anna Serra',         7, '2024-07-01', 3100000),\n  (14,'Roberto Villa',      8, '2025-02-17', 2900000),\n  (15,'Ilaria Costa',      11, '2025-09-08', 2950000);\n\n-- ------------------------------------------------------------------- dim_date\n-- 2025-01-01 to 2026-12-31, generated rather than typed. Italian public holidays\n-- are marked because \"sales per working day\" is a real reporting requirement and\n-- Ferragosto is not a normal Friday.\nINSERT INTO dim_date (d, year, month, day, quarter, iso_week, day_of_week, is_weekend, is_holiday, holiday_name)\nWITH RECURSIVE cal(d) AS (\n  SELECT '2025-01-01'\n  UNION ALL\n  SELECT date(d, '+1 day') FROM cal WHERE d < '2026-12-31'\n)\nSELECT\n  d,\n  CAST(strftime('%Y', d) AS INTEGER),\n  CAST(strftime('%m', d) AS INTEGER),\n  CAST(strftime('%d', d) AS INTEGER),\n  (CAST(strftime('%m', d) AS INTEGER) + 2) / 3,\n  CAST(strftime('%W', d) AS INTEGER),\n  CAST(strftime('%w', d) AS INTEGER),\n  CASE WHEN strftime('%w', d) IN ('0','6') THEN 1 ELSE 0 END,\n  CASE WHEN strftime('%m-%d', d) IN\n    ('01-01','01-06','04-25','05-01','06-02','08-15','11-01','12-08','12-25','12-26')\n    THEN 1 ELSE 0 END,\n  CASE strftime('%m-%d', d)\n    WHEN '01-01' THEN 'Capodanno'          WHEN '01-06' THEN 'Epifania'\n    WHEN '04-25' THEN 'Liberazione'        WHEN '05-01' THEN 'Festa del Lavoro'\n    WHEN '06-02' THEN 'Festa della Repubblica' WHEN '08-15' THEN 'Ferragosto'\n    WHEN '11-01' THEN 'Ognissanti'         WHEN '12-08' THEN 'Immacolata'\n    WHEN '12-25' THEN 'Natale'             WHEN '12-26' THEN 'Santo Stefano'\n    ELSE NULL END\nFROM cal;\n\n-- --------------------------------------------------------------------- orders\n-- ~1 800 orders across two years, weighted so recent months have more, and with\n-- a realistic status mix: most delivered, some in flight, a few cancelled.\nINSERT INTO orders (id, customer_id, status, placed_at, shipped_at, delivered_at, total_cents, version)\nWITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM seq WHERE n < 1800),\nbase AS (\n  SELECT n,\n         1 + (n * 17) % 40                                   AS customer_id,\n         date('2025-01-01', '+' || ((n * 397) % 700) || ' days') AS d,\n         (n * 31) % 100                                      AS roll\n  FROM seq\n)\nSELECT\n  n,\n  customer_id,\n  CASE WHEN roll < 6  THEN 'cancelled'\n       WHEN roll < 12 THEN 'draft'\n       WHEN roll < 20 THEN 'submitted'\n       WHEN roll < 32 THEN 'confirmed'\n       WHEN roll < 48 THEN 'shipped'\n       ELSE 'delivered' END,\n  d || 'T' || printf('%02d', 8 + (n % 10)) || ':' || printf('%02d', (n * 7) % 60) || ':00Z',\n  CASE WHEN roll >= 32 THEN date(d, '+' || (1 + n % 4) || ' days') || 'T10:00:00Z' END,\n  -- Delivery is derived FROM the ship offset, not computed independently, or\n  -- ck_orders_delivered rejects the rows where the two happen to cross. A seed\n  -- that has to be loaded with constraints disabled is not testing the schema.\n  CASE WHEN roll >= 48 THEN date(d, '+' || (1 + n % 4 + 2 + n % 5) || ' days') || 'T14:00:00Z' END,\n  0,    -- filled in below, from the lines. See the UPDATE at the end.\n  1\nFROM base;\n\n-- ---------------------------------------------------------------- order lines\n-- One to four lines per order. The unit price is the list price adjusted by a\n-- small per-order discount, so historical prices genuinely differ from current\n-- ones — which is the whole point of storing them. See chapter 05.\nINSERT INTO order_lines (order_id, line_no, product_id, quantity, unit_price_cents)\nWITH RECURSIVE ln(order_id, line_no, max_lines) AS (\n  SELECT id, 1, 1 + (id * 13) % 4 FROM orders\n  UNION ALL\n  SELECT order_id, line_no + 1, max_lines FROM ln WHERE line_no < max_lines\n)\nSELECT\n  ln.order_id,\n  ln.line_no,\n  p.id,\n  1 + (ln.order_id * 7 + ln.line_no * 3) % 5,\n  -- 0%, 3%, 5% or 8% off the list price, deterministically.\n  p.list_price_cents - (p.list_price_cents * (CASE (ln.order_id * 7 + ln.line_no) % 4\n                                                WHEN 0 THEN 0 WHEN 1 THEN 3\n                                                WHEN 2 THEN 5 ELSE 8 END)) / 100\nFROM ln\nJOIN products p\n  -- 13 and 5 are both coprime with 22, so all 22 live products appear.\n  -- (11 and 29 are not: 11*k mod 22 only ever yields 0 or 11.)\n  ON p.id = 1 + ((ln.order_id * 13 + ln.line_no * 5) % 22)   -- 1..22: never the discontinued two\nWHERE NOT EXISTS (\n  -- Respect uq_lines_product: skip a line that would duplicate a product on the\n  -- same order. A seed that violates its own constraints is not a seed.\n  SELECT 1 FROM order_lines x\n  WHERE x.order_id = ln.order_id\n    AND x.product_id = 1 + ((ln.order_id * 13 + ln.line_no * 5) % 22)\n);\n\n-- Denormalised total, written from the lines it is derived from.\n-- This is a deliberate, NAMED denormalisation: orders.total_cents is a cached\n-- aggregate of order_lines, maintained here at load time and by the application\n-- on every line change. A denormalised column with no stated mechanism is a bug\n-- that has not happened yet. See chapter 05.\nUPDATE orders\nSET total_cents = COALESCE(\n  (SELECT SUM(quantity * unit_price_cents) FROM order_lines l WHERE l.order_id = orders.id), 0);\n\n-- ------------------------------------------------------------------- payments\n-- Only orders past 'confirmed' are paid, and a few are part-paid, so the\n-- outstanding-balance view has something to say.\nINSERT INTO payments (id, order_id, amount_cents, method, paid_at, external_ref)\nSELECT\n  ROW_NUMBER() OVER (ORDER BY o.id),\n  o.id,\n  CASE WHEN o.id % 11 = 0 THEN o.total_cents / 2 ELSE o.total_cents END,\n  CASE o.id % 4 WHEN 0 THEN 'transfer' WHEN 1 THEN 'card'\n                WHEN 2 THEN 'transfer' ELSE 'credit' END,\n  date(substr(o.placed_at, 1, 10), '+' || (1 + o.id % 5) || ' days') || 'T11:30:00Z',\n  'PAY-' || printf('%08d', o.id)\nFROM orders o\nWHERE o.status IN ('confirmed','shipped','delivered')\n  AND o.total_cents > 0;\n\n-- --------------------------------------------------------------------- events\n-- One row per state transition the order has actually been through. Written in\n-- the same transaction as the transition in the real system; generated here.\nINSERT INTO order_events (order_id, from_status, to_status, at, actor)\nSELECT id, NULL, 'draft', placed_at, 'system' FROM orders\nUNION ALL\nSELECT id, 'draft', 'submitted', placed_at, 'customer' FROM orders\n  WHERE status NOT IN ('draft','cancelled')\nUNION ALL\nSELECT id, 'submitted', 'confirmed', placed_at, 'sales' FROM orders\n  WHERE status IN ('confirmed','shipped','delivered')\nUNION ALL\nSELECT id, 'confirmed', 'shipped', shipped_at, 'warehouse' FROM orders\n  WHERE status IN ('shipped','delivered')\nUNION ALL\nSELECT id, 'shipped', 'delivered', delivered_at, 'courier' FROM orders\n  WHERE status = 'delivered'\nUNION ALL\nSELECT id, 'submitted', 'cancelled', placed_at, 'sales' FROM orders\n  WHERE status = 'cancelled';\n\n-- --------------------------------------------------------------------- outbox\n-- A handful of pending messages, so the \"claim a queue row\" lab has something\n-- to claim. See chapter 24.\nINSERT INTO outbox (topic, payload, created_at)\nSELECT 'order.shipped',\n       '{\"orderId\":' || id || ',\"customerId\":' || customer_id || '}',\n       shipped_at\nFROM orders\nWHERE status = 'shipped'\nLIMIT 25;\n";
self.FORGE_DB_HASH = "e5a91f7086e656ed";
